python3 << 'EOF'
import pandas as pd, numpy as np
inv = pd.read_csv('dataset/invoices.csv')
sus_sellers = {4612,8382,4691,3915,6703,7951,6453,2029}
shells4 = {1967,2950,3554,5765}
shells7 = {3495,8285,8770,7021,4521,1060,8810}

inv['flag'] = ''
inv.loc[inv.seller_id.isin(sus_sellers),'flag'] += 'S:'+''
def tag(r):
    t=[]
    if r.seller_id in sus_sellers: t.append(f'sell{r.seller_id}')
    if r.buyer_id in shells4: t.append(f'shell4-{r.buyer_id}')
    if r.buyer_id in shells7: t.append(f'shell7-{r.buyer_id}')
    if r.buyer_id in (12345679,12345680): t.append('extbuy')
    if r.invoice_id>=2_000_000: t.append('BIGID')
    return ','.join(t)
inv['tag'] = inv.apply(tag, axis=1)
flagged = inv[inv.tag!='']
print('flagged rows and their positions:')
runs=[]
prev=None; start=None
for i,t in zip(flagged.index, flagged.tag):
    print(i, t) if i<300 or i>8990 else None
print('\ntotal flagged:', len(flagged), 'index range:', flagged.index.min(), flagged.index.max())
print('\nrow index histogram of flagged:', np.histogram(flagged.index, bins=[0,50,100,150,200,250,300,400,9000,9004])[0])
EOF

