def tag(r):
    t=[]
    if r.seller_id in sus_sellers: t.append(f'sell{r.seller_id}')
    if r.buyer_id in shells4: t.append(f'shell4buy-{r.buyer_id}')
    if r.buyer_id in shells7: t.append(f'shell7buy-{r.buyer_id}')
    if r.buyer_id in (12345679,12345680): t.append('extbuy')
